/** A sentence about a possible use, a limitation, or an embedded element is not
 * a manufacturer's statement identifying the device being imported. */
function declaredDescription(text: string): ModelCategoryEvidence | undefined {
  if (/\b(?:used as|if used|not (?:a|an|suitable)|does not|internal|embedded|example|test bench|testbench|library of|sections|copyright|disclaimer)\b/i.test(text)) return undefined
  if (/\b(?:operational amplifier|op[- ]?amp)\b/i.test(text) && /\bcomparator\b/i.test(text)) return { category: 'analog:amplifier-unverified', reason: text }
  for (const [pattern, category] of descriptions) if (pattern.test(text)) return { category, reason: text }
  return undefined
}

/** Only comments adjacent to this exact root declaration may classify it.
 * Library-wide preambles and comments inside dependency subcircuits are ignored. */
function rootComments(model: ImportedSpiceModel): string[] {
  if (!/^\s*\*/.test(model.spice)) return []
  let pending: string[] = [], depth = 0
  for (const raw of model.spice.split(/\r?\n/)) {
    const line = raw.trim()
    const declaration = line.match(/^\.(subckt|model)\s+(\S+)/i)
    if (declaration && depth === 0) {
      if (declaration[2].toLowerCase() === model.id.toLowerCase()) return pending
      if (declaration[1].toLowerCase() === 'subckt') depth++
    } else if (/^\.subckt\b/i.test(line)) depth++
    else if (/^\.ends\b/i.test(line)) depth = Math.max(0, depth - 1)
    if (!depth && line.startsWith('*')) pending.push(line.replace(/^\*+\s*/, ''))
    else if (line) pending = []
  }
  return []
}

function passiveNetwork(model: ImportedSpiceModel): boolean {
  return model.spice.split(/\r?\n/).every(raw => {
    const line = raw.trim()
    return !line || /^[*+.]/.test(line) || /^[RCLKWT]\S*\s/i.test(line)
  })
}

/** Audited original source declarations, not guesses from vendor part prefixes.
 * Every Murata entry has `MURATA P/N` and `Property : L = ... [nH]`; Coilcraft's
 * file caption says `Library of Power Inductors from Coilcraft`.
 * AMP's caption explicitly says `Library of AMP connector and socket models`.
 * The passive-only guard prevents an arbitrary active macro at that path from
 * inheriting a classification from the registered original family. */
function registeredSource(model: ImportedSpiceModel): ModelCategoryEvidence | undefined {
  const source = model.source.label.replaceAll('\\', '/')
  const pspice = source.match(/^PSpice 本地库 \/ tools\/pspice\/library\/([^/]+)$/i)?.[1].toLowerCase()
  if (pspice && ['murata_ind_rf1.lib', 'murata_ind_rf2.lib', 'coilcraft_ind.lib', 'amp.lib'].includes(pspice) && passiveNetwork(model)) {
    if (model.pins.length === 2 && pspice && ['murata_ind_rf1.lib', 'murata_ind_rf2.lib', 'coilcraft_ind.lib'].includes(pspice)) return { category: 'passive:inductor', reason: `已核对原件电感声明：${source}` }
    if (pspice === 'amp.lib') return { category: 'passive:connector', reason: '原件说明：Library of AMP connector and socket models.' }
  }
  const wurth = source.match(/^本机 LTspice \/ Contrib\/Wurth\/([^/]+)\.lib$/i)?.[1].toUpperCase()
  if (wurth && ['WE-DD', 'WE-TDC', 'WE-DPC_HV', 'WE-MCRI', 'WE-CFWI', 'WE-PFC_WITH_AUX'].includes(wurth) && passiveNetwork(model)) {
    if (['WE-DD', 'WE-TDC', 'WE-DPC_HV', 'WE-MCRI', 'WE-CFWI'].includes(wurth)) return { category: 'passive:coupled-inductor', reason: `原件 Kinds 为 Coupled Inductor / Dual Powerchoke：${wurth}` }
    if (wurth === 'WE-PFC_WITH_AUX') return { category: 'passive:power-choke', reason: '原件 Kinds: PFC Chokes；保留辅助绕组，不冒称变压器。' }
  }
  return undefined
}

export function modelCategoryEvidence(model: ImportedSpiceModel): ModelCategoryEvidence | undefined {
  const section = reviewedSectionCategory(model)
  if (section) return section
  for (const text of [model.metadata.type, model.deviceInfo?.function, ...rootComments(model)]) {
    if (!text) continue
    const result = declaredDescription(text)
    if (result) return result
  }
  const reviewedSource = reviewedModelSourceCategory(model)
  if (reviewedSource) return reviewedSource
  const registered = reviewedPropertyCategory(model)
  if (registered) return registered
  return registeredSource(model)
}

