function reviewedPropertyCategory(model: ImportedSpiceModel): ModelCategoryEvidence | undefined {
  const file = model.source.label.replaceAll('\\', '/').match(/^PSpice 本地库 \/ tools\/pspice\/library\/([^/]+)$/i)?.[1].toLowerCase()
  if (!file) return undefined
  const record = reviewedPropertyEvidence.find(item => item.file === file && item.ids.has(model.id.toLowerCase()))
  return record ? { category: record.category, reason: '原件 ' + file.replace(/\.lib$/i, '.prp') + ' / device_info / SYMBOL_NAME=' + record.symbol + '（准确型号记录）' } : undefined
}


